// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        bytes32 assertionId = bytes32(0);
        bool assertedTruthfully = true;

        vm.prank(address(c.optimisticAsserter()));
        c.assertionDisputedCallback(assertionId);

        bool reverted;
        vm.prank(caller);
        try c.requestPrice(bytes32(0), 0, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        assertTrue(reverted, "Non-optimistic asserter must not be able to call requestPrice");
    }
}
